-- THREAD 3
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-43-gather-thee-from-the-four-quarters',
       E'Gather thee from the four quarters — the two houses brought home',
       E'Yahuah promises to gather his scattered people from every direction: *Fear not: for I am with thee: I will bring thy seed from the east, and gather thee from the west; I will say to the north, Give up; and to the south, Keep not back: bring my sons from far, and my daughters from the ends of the earth; Even every one that is called by my name: for I have created him for my glory* (Isaiah 43:5-7). This is the two-house regathering. Isaiah names it plainly: *he shall set up an ensign for the nations, and shall assemble the outcasts of Yashar''el (Israel), and gather together the dispersed of Yahudah (Judah) from the four corners of the earth* (Isaiah 11:12) — the scattered northern house and the dispersed southern house brought home as one, never replaced by another people. Yahusha echoes the ingathering: *many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven* (Matthew 8:11) — the seed of the fathers gathered to the table of the fathers. And the Son of Adam consummates it: *he shall send his angels, and shall gather together his elect from the four winds, from the uttermost part of the earth to the uttermost part of heaven* (Mark 13:27). The four quarters of Isaiah become the four winds of the final ingathering — the sons and daughters called by His name, brought home.',
       sv.verse_id, ev.verse_id, 'free', 27056
  FROM _s303_isa43_lookup sv, _s303_isa43_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=43 AND sv.verse_number=5
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=43 AND ev.verse_number=7
ON CONFLICT (slug) DO NOTHING;

-- THREAD 4 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-43-behold-i-will-do-a-new-thing',
       E'Behold, I will do a new thing — the second exodus, rivers in the desert',
       E'Yahuah turns his people from the past to the new work springing up: *Remember ye not the former things, neither consider the things of old. Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert* (Isaiah 43:18-19). This is the second-exodus pattern — a way made and water given in the wilderness, *to give drink to my people, my chosen* (43:20) — the same Yahuah names again: *he caused the waters to flow out of the rock for them: he clave the rock also, and the waters gushed out* (Isaiah 48:21). And the new thing opens toward the new creation: *if any man be in Messiah (Christ), he is a new creature: old things are passed away; behold, all things are become new* (2 Corinthians 5:17), consummated in the throne-word *Behold, I make all things new. And he said unto me, Write: for these words are true and faithful* (Revelation 21:5). The new thing that begins as a path through the desert ends in the new heaven and new earth — the former things remembered no more.',
       sv.verse_id, ev.verse_id, 'free', 27059
  FROM _s303_isa43_lookup sv, _s303_isa43_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=43 AND sv.verse_number=18
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=43 AND ev.verse_number=19
ON CONFLICT (slug) DO NOTHING;

-- THREAD 5 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-43-blotteth-out-thy-transgressions-for-mine-own-sake',
       E'Blotteth out thy transgressions for mine own sake — pardon unto teshuvah',
       E'The chapter''s great word of pardon is unconditioned by merit and grounded in Yahuah''s own name: *I, even I, am he that blotteth out thy transgressions for mine own sake, and will not remember thy sins* (Isaiah 43:25). The next chapter seals it: *I have blotted out, as a thick cloud, thy transgressions, and, as a cloud, thy sins: return unto me; for I have redeemed thee* (Isaiah 44:22) — and the call *return unto me* shows the blotting-out is unto teshuvah, never licence. The psalm measures how far the pardon reaches: *As far as the east is from the west, so far hath he removed our transgressions from us* (Psalm 103:12). And it is the heart of the new covenant: *I will forgive their iniquity, and I will remember their sin no more* (Jeremiah 31:34) — the same covenant that writes the law within: *I will put my law in their inward parts, and write it in their hearts* (31:33). Peter preaches this very pardon, and preaches it bound to turning: *Repent ye therefore, and be converted, that your sins may be blotted out, when the times of refreshing shall come from the presence of Yahuah (Lord)* (Acts 3:19). The sin is remembered no more AND the Torah is kept from within — pardon and obedience together, never pardon instead of obedience.',
       sv.verse_id, ev.verse_id, 'free', 27062
  FROM _s303_isa43_lookup sv, _s303_isa43_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=43 AND sv.verse_number=25
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=43 AND ev.verse_number=25
ON CONFLICT (slug) DO NOTHING;

